// Authored NOT_RUN. No numerical fitter acceptance.
use kni_core::fitter_requirements::{FitterRequirements,missing,SourceFitRun,inspect_run,RunInputBoundary};
use kni_core::decision_evidence_envelope::PinClaim;
use kni_core::reference_slice::Point;
fn pin()->PinClaim{PinClaim{algorithm:"fixture".into(),claimed_digest:"unverified".into(),subject_ref:"source".into()}}
#[test]fn source_pin_does_not_fill_math(){let r=FitterRequirements{mechanism_source:pin(),normal_equations:None,sample_weight_definition:None,tangent_convention:None,error_measure:None,tolerance_calibration:None,determinant_policy:None,reparameterization_rule:None,termination_policy:None,split_seam_policy:None};assert_eq!(missing(&r).len(),9);}
#[test]fn run_preserves_explicit_tangent_and_source(){let mut r=SourceFitRun{source_pin:pin(),frame_pin:pin(),ring_index:2,span_indices:vec![3,4],points:vec![Point{x:0.,y:0.},Point{x:1.,y:1.}],start_tangent:Point{x:2.,y:0.},end_tangent:Point{x:-3.,y:0.},tangent_binding:pin(),seam_binding:pin()};assert!(inspect_run(&r).is_empty());assert_eq!(r.start_tangent.x,2.);assert_eq!(r.end_tangent.x,-3.);r.points[0].x=f64::NAN;r.start_tangent=Point{x:0.,y:0.};let findings=inspect_run(&r);assert!(findings.contains(&RunInputBoundary::NonFinitePoint));assert!(findings.contains(&RunInputBoundary::ZeroTangent));}
#[test]fn siblings_and_claims_retained_without_solver(){use kni_core::fitter_requirements::inspect_runs;let run=SourceFitRun{source_pin:pin(),frame_pin:pin(),ring_index:0,span_indices:vec![0],points:vec![Point{x:0.,y:0.},Point{x:1.,y:1.}],start_tangent:Point{x:1.,y:0.},end_tangent:Point{x:-1.,y:0.},tangent_binding:pin(),seam_binding:pin()};let mut bad=run.clone();bad.ring_index=7;bad.points.clear();let result=inspect_runs(vec![bad,run]);assert_eq!(result.len(),2);assert_eq!(result[0].retained_source.ring_index,7);assert!(result[0].boundaries.contains(&RunInputBoundary::NoSamples));assert!(result[1].boundaries.is_empty());assert_eq!(result[1].retained_source.source_pin.claimed_digest,"unverified");}
